  private static Object applyLogicalType(Schema schema, Object value) {
    if (schema == null) {
      return value;
    }
    // Choose the non-null schema when the field schema is represented as union schema. Only then, the avro library
    // is able to determine the correct logical type for the field.
    Schema fieldSchema = schema;
    if (fieldSchema.isUnion()) {
      List<Schema> fieldSchemas = fieldSchema.getTypes();
      for (Schema curSchema: fieldSchemas) {
        if (curSchema.getLogicalType() != null) {
          fieldSchema = curSchema;
          break;
        }
      }
    }
    LogicalType logicalType = LogicalTypes.fromSchemaIgnoreInvalid(fieldSchema);
    if (logicalType == null) {
      return value;
    }
    Conversion<?> conversion = AvroSchemaUtil.findConversionFor(logicalType.getName());
    if (conversion == null) {
      return value;
    }
    return Conversions.convertToLogicalType(value, fieldSchema, logicalType, conversion);
  }

  /**
   * Recursively converts all logical type fields within the given Avro record to their corresponding Java types.
   * Logical types at any depth in the schema (including those nested inside arrays, maps and records) are resolved.
   * For example, UUID logical types are converted to {@link java.util.UUID}, timestamp-millis logical types to
   * {@link java.time.Instant} and decimal logical types to {@link java.math.BigDecimal}. Fields that do not carry a
   * logical type (and are not arrays/maps/records that contain one) are passed through unchanged.
   *
   * @param record Avro record whose logical type fields should be converted
   * @return A new {@link GenericRecord} with all logical type fields converted, or {@code null} if the input is
   *     {@code null}.
   */
  public static GenericRecord convertLogicalType(GenericRecord record) {
    if (record == null) {
      return null;
    }
    Schema schema = record.getSchema();
    GenericRecord convertedRecord = new GenericData.Record(schema);
    for (Schema.Field field : schema.getFields()) {
      Object value = record.get(field.name());
      convertedRecord.put(field.name(), convertValue(value, field.schema()));
    }
    return convertedRecord;
  }

  /**
   * Converts a single value according to its schema. Records are processed recursively, arrays and maps have their
   * elements/values converted, and leaf values with a logical type are converted to their Java type. Any other value
   * is returned unchanged.
   */
  private static Object convertValue(Object value, Schema schema) {
    if (value == null || schema == null) {
      return value;
    }
    Schema resolvedSchema = resolveSchema(schema);
    switch (resolvedSchema.getType()) {
      case RECORD:
        return value instanceof GenericRecord ? convertLogicalType((GenericRecord) value) : value;
      case ARRAY:
        return value instanceof Collection ? convertArray((Collection<?>) value, resolvedSchema.getElementType())
            : value;
      case MAP:
        return value instanceof Map ? convertMap((Map<?, ?>) value, resolvedSchema.getValueType()) : value;
      default:
        return applyLogicalType(resolvedSchema, value);
    }
  }

  private static Object convertArray(Collection<?> collection, Schema elementSchema) {
    List<Object> convertedElements = new ArrayList<>(collection.size());
    for (Object element : collection) {
      convertedElements.add(convertValue(element, elementSchema));
    }
    return convertedElements;
  }

  private static Object convertMap(Map<?, ?> map, Schema valueSchema) {
    Map<Object, Object> convertedMap = new HashMap<>();
    for (Map.Entry<?, ?> entry : map.entrySet()) {
      convertedMap.put(entry.getKey(), convertValue(entry.getValue(), valueSchema));
    }
    return convertedMap;
  }

  /**
   * Resolves the effective schema used for conversion. For union schemas, the sub-schema carrying a logical type is
   * preferred; otherwise the first non-null sub-schema is used so that nested records/arrays/maps can be processed.
   */
  private static Schema resolveSchema(Schema schema) {
    if (schema.getType() != Schema.Type.UNION) {
      return schema;
    }
    Schema firstNonNull = null;
    for (Schema curSchema : schema.getTypes()) {
      if (curSchema.getLogicalType() != null) {
        return curSchema;
      }
      if (firstNonNull == null && curSchema.getType() != Schema.Type.NULL) {
        firstNonNull = curSchema;
      }
    }
    return firstNonNull != null ? firstNonNull : schema;
  }
